      "head": "གཟུགས་ལ་སོགས་ལ་ལྡོག་སོགས་རྟགས།",
      "tail": "ཞེས་པའི་གཞུང་འདིས་ཐེག་ཆེན་སྦྱོར་"
    },
    {
      "label": "QUOTE",
      "head": "གཟུགས་ལ་བདེན་ཞེན་མངོན་གྱུར་བ་",
      "tail": "དེས་ལྷག་མ་རྣམས་ལ་རིགས་འགྲེ་ཟེར་རོ། །"
    },
    {
      "label": "QUOTE",
      "head": "གཟུགས་ལ་སོགས་ལ་ལྡོག་སོགས་རྟགས།",
      "tail": "ཞེས་སོགས་ཀྱི་གཞུང་དེས་བྱང་སེམས་"
    },
    {
      "label": "QUOTE",
      "head": "ལ་ལར་རིགས་མ་ངེས་པ་ཡིན་ཀྱང་ངེས་པར་",
      "tail": "ཞེས་གསུངས་པ་དང་འགལ་ལོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "འགྲེལ་ཆེན་ལས།",
      "head": "གཟུང་བར་བྱའོ་ཞེས་པ་ནི། ། ནུས་",
      "tail": "དེ་ནི་རང་བཞིན་ཡིན་པར་བརྗོད། །"
    },
    {
      "label": "QUOTE",
      "head": "དེ་འདིར་ཕྱིར་མི་ལྡོག་པའི་ཚོགས།",
      "tail": "ཕྱིར་མི་ལྡོག་པའི་དགེ་འདུན་ཡིན་ནོ་ཞེས་"
    },
    {
      "label": "QUOTE",
      "head": "ངེས་འབྱེད་ཡན་ལག་ལ་གནས་པའི། ། ཕྱིར་",
      "tail": "ཞེས་དང་།"
    },
    {
      "label": "QUOTE",
      "head": "སློབ་པ་ཕྱིར་མི་ལྡོག་པའི་ཚོགས།",
      "tail": "ཞེས་དང་།"
    },
    {
      "label": "QUOTE",
      "head": "ངེས་འབྱེད་ཡན་ལག་ནས་གཟུང་སྟེ། །",
      "tail": "ཞེས་སོགས་རྩ་འགྲེལ་གྱིས་བསྟན་ནོ། །"
    },
    {
      "label": "QUOTE",
      "head": "སློབ་པ་ཕྱིར་མི་ལྡོག་པའི་ཚོགས།",
      "tail": "ཞེས་ཕྱིར་མི་ལྡོག་པའི་དགེ་འདུན་གསུངས་"
    },
    {
      "label": "QUOTE",
      "head": "ངེས་འབྱེད་ཡན་ལག་ནས་གཟུང་སྟེ། །",
      "tail": "ཞེས་སོགས་རྩ་འགྲེལ་གྱིས་བསྟན་ནོ། །"
    },
    {
      "label": "QUOTE",
      "head": "གཟུགས་ལ་སོགས་ལ་ལྡོག་སོགས་རྟགས།",
      "tail": "རྣམ་པ་ཉི་ཤུར་བརྗོད་པ་ཡིས། །"
    },
    {
      "label": "QUOTE",
      "head": "ངེས་འབྱེད་ཡན་ལག་ལ་གནས་པའི། །",
      "tail": "ཞེས་པས་ཆོས་ཅན།"
    },
    {
      "label": "QUOTE",
      "head": "རྟགས་ནི་ཉི་ཤུ་དེ་དག་གི །",
      "tail": "ཞེས་པས་གཏན་ཚིགས།"
    },
    {
      "label": "QUOTE",
      "head": "དྲོད་དང་རྩེ་མོ་བཟོད་བཅས་དང་། ། ཆོས་",
      "tail": "ཆེན་པོར་སྒྲུབ་པའི་རང་བཞིན་གྱི་རྟགས་སུ་"
    },
    {
      "label": "QUOTE",
      "head": "རྫོགས་པའི་བྱང་ཆུབ་ལས་མི་ལྡོག །",
