    },
    {
      "label": "QUOTE",
      "head": "བྱང་ཆུབ་སེམས་དཔའ་",
      "tail": "ཞེས་པས་ཆོས་ཅན་དང་།"
    },
    {
      "label": "QUOTE",
      "head": "མཚན་ཉིད་ཡིན་པར་ཤེས་པར་བྱ། །",
      "tail": "ཞེས་པས་ཁྱབ་པ་བསྟན་ཏོ། །"
    },
    {
      "label": "QUOTE",
      "head": "དེ་འདྲའི་སྐད་ཅིག་བཅུ་དྲུག་ནི། །",
      "tail": "ཞེས་པས་གཏན་ཚིགས།"
    },
    {
      "label": "QUOTE",
      "head": "བློ་ལྡན་མཐོང་བའི་ལམ་གནས་ཀྱི། །",
      "tail": "ཞེས་པས་ཆོས་ཅན།"
    },
    {
      "label": "QUOTE",
      "head": "སྐྱེ་བ་དང་ནི་འགག་པ་དང་། །",
      "tail": "ཞེས་པའི་གཏན་ཚིགས།"
    },
    {
      "label": "QUOTE",
      "head": "བློ་ལྡན་སྒོམ་པའི་ལམ་གནས་པའི། ། ཕྱིར་",
      "tail": "མི་ལྡོག་པའི་རྟགས་དག་ཡིན། །"
    },
    {
      "label": "QUOTE",
      "head": "རྒྱུ་དང་ལམ་དང་སྡུག་བསྔལ་དང་། །",
      "tail": "ཞེས་སོགས་གསུངས་པ་བཞིན་ནོ། །"
    },
    {
      "label": "QUOTE",
      "head": "དེ་ལྟར་ན་བཟོད་དང་ཤེས་པའི་སྐད་ཅིག་",
      "tail": "མ་བཅུ་དྲུག་གིས་བསྡུས་པ་འདི་རྣམས་"
    },
    {
      "label": "QUOTE",
      "head": "རུང་བ་ཉིད་རྗེས་སུ་དཔག་པས་གཟུང་",
      "tail": "བར་བྱའོ་ཞེས་པས་བསྟན་ཏེ།"
    },
    {
      "label": "QUOTE",
      "head": "གཟུང་བར་བྱའོ་ཞེས་པ་ནི།",
      "tail": "མདོ་ལས་རྣམ་པ་དང་།"
    },
    {
      "label": "QUOTE",
      "head": "དེ་གཉིས་ཡང་དང་ཡང་དུ་ནི། །",
      "tail": "ཞེས་གསུངས་པའི་ཕྱིར།"
    },
    {
      "label": "QUOTE",
      "head": "རྒྱལ་བའི་སྲས་པོས་ས་ཐོབ་ཀྱང་། ། བློ་",
      "tail": "བརྟན་པ་ཉིད་མ་ཡིན་ཏེ། །"
    }
  ]
